PREFIX proveedores: <https://w3id.org/rastro/proveedores#>
SELECT (SUM(?amt) AS ?total) WHERE {
  { SELECT DISTINCT ?c ?amt WHERE {
      ?c a proveedores:Contract ; proveedores:agency ?ag ; proveedores:amount ?amt ; proveedores:supplier ?s .
      ?ag proveedores:name ?an . FILTER(STR(?an) = "Department of Defense")
      {
        ?s a proveedores:ForeignParentSupplier .
      } UNION {
        ?s proveedores:watchlistMatch ?e .
        ?e proveedores:entryType ?t . FILTER(STR(?t) = "Entity")
      } UNION {
        ?s proveedores:group ?g . ?g proveedores:watchlistMatch ?e2 .
        ?e2 proveedores:entryType ?t2 . FILTER(STR(?t2) = "Entity")
      }
  } }
}
